from .repository import find_existing_emails, put_contact

_CONTACT_FIELDS = frozenset({"email", "name"})

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _clean_text(value, index, field):
    if not isinstance(value, str):
        raise ValueError(f"row {index}: {field} must be a string")
    return value.strip()

def _normalize_row(row, index):
    if not isinstance(row, dict):
        raise ValueError(f"row {index} must be an object")
    if set(row) != _CONTACT_FIELDS:
        raise ValueError(f"row {index} must have exactly the fields 'email' and 'name'")
    email = _clean_text(row["email"], index, "email")
    name = _clean_text(row["name"], index, "name")
    if any(ch.isspace() for ch in email):
        raise ValueError(f"row {index}: email must not contain whitespace")
    local, separator, domain = email.partition("@")
    if not separator or not local or not domain or "@" in domain:
        raise ValueError(f"row {index}: email must contain exactly one '@' with nonempty sides")
    if not name:
        raise ValueError(f"row {index}: name must be nonempty")
    return email.lower(), name

def _validate_batch(rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    seen = set()
    contacts = []
    for index, row in enumerate(rows):
        email, name = _normalize_row(row, index)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        contacts.append((email, name))
    return contacts

def import_contacts(connection, rows):
    contacts = _validate_batch(rows)
    if not contacts:
        return {"inserted": 0, "updated": 0}
    try:
        connection.execute("BEGIN IMMEDIATE")
        existing = find_existing_emails(connection, [email for email, _ in contacts])
        for email, name in contacts:
            put_contact(connection, email, name)
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    inserted = sum(1 for email, _ in contacts if email not in existing)
    return {"inserted": inserted, "updated": len(contacts) - inserted}
EOF
